        "copyright": "",
        "creditline": "Harvard Art Museums/Arthur M. Sackler Museum, Gift of Elizabeth Gowing, Harborne W. Stuart, Peggy Coolidge, and the Estate of W.I. Stuart in memory of Mr. and Mrs. Willoughby H. Stuart, Jr.",
        "department": "Department of Islamic & Later Indian Art",
        "division": "Asian and Mediterranean Art",
        "contact": "am_asianmediterranean@harvard.edu",
        "description": "Marasali Prayer Rug.  Deep blue field with horizontal rows of variously colored botehs forming diagonals by type and ornament, surrounded by reciprocal palisade in red and blue.  Three guard borders of five petaled flowers, white ground outer main border with bunches of grapes; yellow ground inner main border  with fruits.  Around the niche area, an incomplete human form, 2 ewers (ibrik), a piece of jewelry or a comb, and a date,1908, repeated 3 times.\r\n\r\nWarp: 2 S plied Z spun white undyed wool on one level.  Weft: 1 Z spun yarn in 2 shoots, or occasionally in 2 parallel + 1 construction.  Pile: 3, or occasionally 2 (depending on color), S plied Z spun.  Pile color: 2 + 3 ply red, 3 ply green, 3 ply yellow, 2 ply green; all 3 ply: dark crimson red, dull medium red, very dark purple red, dark navy blue, medium blue, medium green, light green, dark yellow, very pale yellow, slightly corrosive brown, white, light brown wool; small areas of undyed and dark red silk.  Both selvedges: 2 warps wrapped in magenta silk or shiny (mercerized?) cotton.  Top: 1/2 cm. blue countered soumak brocade, 2 cm. tapestry weave, stripped, 1 1/2 cm. knot lace.  Bottom: 1 cm. knot lace based on 4 warps, 1 cm. left to right countered soumak in brown, dark yellow, and red.",
        "provenance": "",
        "commentary": "",
