        "provenance": "Commissioned by William Hazleton Folwell, Philadelphia, 1878. Purchased by Grenville L. Winthrop, New York, NY, 1942 [through Martin Birnbaum], gift; to the Fogg Art Museum, 1942.\r\n\r\n",
        "commentary": "",
        "labeltext": "This painting portrays a group of exotic objects from the collection of William Hazleton Folwell, the Philadelphia dry-goods importer who commissioned the work. Comprising genuine antiques, contemporary ceramics, and modern replicas, Folwell’s collection reflects the eclecticism of Victorian taste and the influence of the Philadelphia Centennial Exposition held in 1876. This international fair introduced Americans to objects from around the world and sparked widespread interest in collecting exotica.\r\n\r\n\r\nFamous for his trompe l’oeil paintings, Harnett was among the most technically skilled painters in late nineteenth-century America. Few painters were as adept at rendering the surfaces of material objects. Here Harnett uses thick impasto to describe the incised surface of the torch stand, and staccato brushwork to define the woven texture of the tablecloth.",
