        "dimensions": "266.7 x 121.9 cm (105 x 48 in.)",
        "copyright": "© 1974 Mimi Smith",
        "creditline": "Harvard Art Museums/Fogg Museum, Margaret Fisher Fund",
        "department": "Department of Modern & Contemporary Art",
