        "standardreferencenumber": "",
        "dimensions": "Sheet: 62.2 x 90.2 cm (24 1/2 x 35 1/2 in.)\r\nFrame: 90 x 119.5 x 4.5 cm (35 7/16 x 47 1/16 x 1 3/4 in.)",
        "copyright": "© Ellen Gallagher",
        "creditline": "Harvard Art Museums/Fogg Museum, Margaret Fisher Fund",
        "department": "Department of Prints",
        "division": "Modern and Contemporary Art",
        "contact": "am_moderncontemporary@harvard.edu",
        "description": "",
        "provenance": "[Two Palms Press, Inc., New York, New York], sold; to Harvard University Art Museums, August 2006.",
        "commentary": "Ellen Gallagher's Abu Simbel print pushes the definition of printmaking to its outer limits. In 2000, she was asked to do an intervention at the Freud Museum in London and got interested in the photogravure of Abu Simbel, an ancient Egyptian site, hanging in his library. She determined to make a copy of the original photogravure and manipulate it with her race, history, and identity driven iconography. The \"reprinted\" photogravure has gold leaf, crystals, plasticine, and blue fur collaged to its surface, as well as some washes of watercolor. She describes it as \"a tricked-out, multi-directional flow from Freud to ancient Egypt to Sun Ra to George Clinton.\" \r\nFeatured prominently in the upper left is a space ship shooting fireballs at the Egyptian monument that makes reference to the blaxploitation film, Space is the Place, in which Sun Ra has been sent to earth to rescue downtrodden African Americans and take them back to his astral utopia. He finds opposition from the Overseer, a black man who rides around in a huge Cadillac, oppressing other blacks. In Gallagher's print, the black pharaohnic figures sit atop Cadillac grills, surrounded by the decapitated heads of other black men, the victims of their oppression. In Sun Ra's movie, the Overseer is always has a woman on each arm and here the pharaohs are accompanied by two nurses, one of Gallagher's favorite characters. The nurse is an allusion to Eunice Rivers, the nurse who although caring and sympathetic, followed the orders of the doctors who conducted the Tuskegee syphilis experiments. She has become an exemplar of black complicity in the black subjugation. The same self-subjugation is exemplified by the three small figures on the right-a white man, an African American, and a black African-who Gallagher described to David Lasry, the publisher of the print, as \"Harlem real estate developers.\"",
        "labeltext": "",
