        "classification": "Sculpture",
        "classificationid": 30,
        "medium": "Stoneware with red glaze",
        "technique": "Relief",
        "techniqueid": 157,
        "period": "",
        "periodid": "",
        "century": "21st century",
        "culture": "German",
        "style": "",
        "signed": "",
