        "edition": "",
        "standardreferencenumber": "",
        "dimensions": "sight: 80.1 x 61.7 x 4.9 cm",
        "copyright": "© Rosemarie Trockel / Artists Rights Society (ARS), New York",
        "creditline": "Harvard Art Museums/Busch-Reisinger Museum, Purchase through the generosity of Wilhelm Winterstein",
        "department": "Busch-Reisinger Museum",
        "division": "Modern and Contemporary Art",
        "contact": "am_moderncontemporary@harvard.edu",
        "description": "Ceramic made from a mould formed from rare meat. Intense, unevenly applied, red glaze maintains the strong allusion to blood and flesh. The organic forms are structured by the rectilinear \"grid\" of a central spine and \"ribs\", the slats and wooden structure of the eponymous \"Shutter.\"\r\n\r\n",
        "provenance": "Barbara Gladstone Gallery, representing the artist, 2006.\r\n",
        "commentary": "",
        "labeltext": "In the German art scene of the 1980s, dominated by male painters, Cologne-based artist Rosemarie Trockel emerged as an oppositional figure. As she did then, she continues to address the body, sexuality, and violence. In Shutter (c), ragged edges and blood-red glaze allude to the object used to cast the piece: a slab of raw meat. The linear indentations, suggestive of a shutter, also evoke ribs and a spine. The work recalls traditional painting subjects, such as Dutch genre scenes of butchers’ stalls, while the shutter structure’s similarity to bones suggests the history of casting sculpture from the human body. Like her best-known work — large-scale machine-knitted panels — this sculpture combines high art traditions with craft materials. Trockel reinterprets the neatly ordered grid of modernist painting, importing its refined form into ceramics, usually a medium of craft. The grid appears as a futile attempt to tame the unrelenting materiality of the sculpture, rooted in bodily forms and tinged with the suggestion of violence.",
        "imagecount": 1,
        "mediacount": 0,
