        "dimensions": "144.8 x 71.1 cm (57 x 28 in.)\r\nframe: 154.6 x 80.7 x 6 cm (60 7/8 x 31 3/4 x 2 3/8 in.)",
        "copyright": "",
        "creditline": "Harvard Art Museums/Fogg Museum, Gift of the Estate of Harriet Anna Niel",
        "department": "Department of American Paintings, Sculpture & Decorative Arts",
        "division": "European and American Art",
        "contact": "am_europeanamerican@harvard.edu",
        "description": "",
        "provenance": "Descent through the family from the sitter's parents, Joseph and Waitstill Peck Leavens, Lansingburgh, NY; to their daughter, Anna Maullin Niel; to her granddaughter, Harriet Anna Niel; her gift to the Fogg Art Museum, 1945",
        "commentary": "",
        "labeltext": "Phillips was an itinerant, self-taught painter who spent much of his career traveling through small towns in the Berkshires and the Connecticut River Valley. An able marketer, he promoted his portraits in local newspapers as having been done “in a correct style” with “perfect shadows and elegant dresses in the prevailing fashion of the day.”\r\nThis portrait, among the most celebrated and widely recognized works in Phillips’s oeuvre, depicts the eldest daughter of the Leavens family of Lansingburgh, New York. She is portrayed as a slender, stylish young woman dressed in a gown in the Empire style, which was adopted from France.\r\nWith its simple geometries and pastel palette punctuated by flashes of blue, orange, and red, the portrait looks forward to the modernist abstractions of the early twentieth century. Phillips’s work held particular appeal for American painters of that era.",
