                "idsid": 23074201,
                "format": "image/jpeg",
                "description": "A young, probably adolescent girl with reddish brown hair, pale skin, and thin arms, stands facing us with a calm, assured smile. In front of a beige-pink wall, she wears a long peach colored dress, almost cone shaped, that extends from the floor to a short, low cut bodice and short, gathered sleeves. She wears a dark brown ribbon in her hair, jeweled earrings, and a necklace with a double chain and a red gemstone. In her left hand she holds a red and black bag, and in her right she grips the handle of a closed umbrella whose point rests on the floor.",
