        "classification": "Prints",
        "classificationid": 23,
        "medium": "Etching on off-white antique laid paper",
        "technique": "Etching",
        "techniqueid": 116,
        "period": "",
        "periodid": "",
        "century": "17th century",
        "culture": "Flemish",
        "style": "",
        "signed": "",
        "state": "i/vii",
        "edition": "",
        "standardreferencenumber": "M.-H. 4; Antwerp/Amsterdam 5",
        "dimensions": "platemark: 24.5 x 15.7 cm (9 5/8 x 6 3/16 in.)\r\nsheet: 26 x 17.5 cm (10 1/4 x 6 7/8 in.)\r\nframed: 57.8 x 47 x 2.5 cm (22 3/4 x 18 1/2 x 1 in.)",
        "copyright": "",
        "creditline": "Harvard Art Museums/Fogg Museum, Gift of Walter C. Klein, Class of 1939",
        "department": "Department of Prints",
        "division": "European and American Art",
        "contact": "am_europeanamerican@harvard.edu",
        "description": "",
        "provenance": "Sir Peter Lely (Lugt 2092). Cledenin J. Ryan, Short Hills, New Jersey, sold [through his sale, Parke Bernet, New York, January 19-20, 1940, lot 112]. Mr. and Mrs. W. Clifford Klenk, Long Island, New York. [Sotheby Parke Bernet, New York, February 16, 1979, lot 610]. [R. M. Light & Co., Boston], sold; to Mr. and Mrs. Walter C. Klein, New York, gift; to Harvard Art Museums, 2008.",
        "commentary": "The Iconography is a collection of portrait prints made after drawings and paintings by van Dyck. Eighteen were etched by the artist himself, although the majority are engravings made by a variety of printmakers. This compilation of portraits of princes, politicians, soldiers, statesmen, scholars, art connoisseurs and most importantly artists, a survey of the most distinguished men and women of his time, went through many editions. The edition published by Martinus van den Enden during van Dyck's lifetime consisted of eighty portraits. Van Dyck prepared these prints by making oil sketches and drawings in black chalk, sometimes washed with brown ink. \r\n\r\nMany of these eighteen etched portraits by van Dyck are rare first state impressions, including this one of the artist's Self-Portrait. The majority of the other eighteen are depictions of artists as well, including Jan and Pieter Brueghel, Lucas Vorsterman and Paulus Pontius-important reproductive engravers of Rubens's work, and Cornelis Anthoniszoon.\r\n",
        "labeltext": "",
