        "standardreferencenumber": "",
        "dimensions": "55.4 x 42.1 cm (21 13/16 x 16 9/16 in.)\r\nframed: 64.6 x 51.4 x 3 cm (25 7/16 x 20 1/4 x 1 3/16 in.)",
        "copyright": "",
        "creditline": "Harvard Art Museums/Busch-Reisinger Museum, Gift of Wilhelm Winterstein through the Acquisitions Committee of the Friends of the Busch-Reisinger Museum in honor of James Cuno on the occasion of the 100th Anniversary of the Museum",
        "department": "Busch-Reisinger Museum",
        "division": "Modern and Contemporary Art",
        "contact": "am_moderncontemporary@harvard.edu",
        "description": "",
        "provenance": "Private collection, Bremen, 1930s. [Neumeisters Moderne, Munich, 16 May 2002, lot 636], sold. Busch-Reisinger Museum, 2003. \r\n\r\nNote: Neumeisters Moderne (May 16, 2002) catalogue, lot 636, repr. col. p. 149.\r\n",
        "commentary": "",
        "labeltext": "The flat terrain, birch trees, and dramatic wide-open skies depicted in these works (2003.4 and 2000.264) are characteristic of Worpswede, a small peasant village near Bremen in northern Germany. It was there in an artist’s colony that Modersohn-Becker, inspired by the region’s rural inhabitants and the simplicity of its landscape, developed her signature “naive” style. Following the teachings at the colony, she applied paint swiftly and directly to the support. With the central position of the birch tree in the scene, she also disrupted a more conventional, picturesque view, while still creating a sense of depth in the small landscape. Girl in a Red Dress (2000.264)  derives the strength of its subject from reduced color and simplified forms. Modersohn-Becker’s style, in particular her thickly painted brushstrokes, shows the influence of postimpressionist painters such as Cézanne, Gauguin, and Van Gogh, whose work she saw during several extended visits to Paris beginning in 1900. In her short career, Modersohn-Becker’s early pursuit of formal simplification and the sensitivity of her themes made her one of the foremost expressionist painters in Germany.",
