                "idsid": 17389079,
                "format": "image/jpeg",
                "description": "The painting show a birch tree in the center, it rises in two trunks from a brown and green foreground to the top of the picture plane. The left trunk shows a branch extending from it to cross the space between the two. The tree is crowned with red, green, and orange leaves. A smaller tree with a white trunk and leaves is behind and to the left. The background is lighter green becoming darker green towards the back and ends with a line of dark trees against a blue sky with thin white clouds.",
