        "standardreferencenumber": "",
        "dimensions": "91.5 x 76.2 cm (36 x 30 in.)",
        "copyright": "© 2004 Glenn Ligon",
        "creditline": "Harvard Art Museums/Fogg Museum, Margaret Fisher Fund",
        "department": "Department of Prints",
        "division": "Modern and Contemporary Art",
        "contact": "am_moderncontemporary@harvard.edu",
        "description": "",
        "provenance": "[Dieu Donné Paper Mill, Inc., New York, New York], sold; to Harvard University Art Museums, December 15, 2005.",
        "commentary": "\"Self-Portrait at Eleven Years Old\" is another example of Glenn Ligon using images and words of his cultural heroes to explore his own identity. The paper-pulp print depicts Stevie Wonder as pictured on his 1977 compilation album, \"Looking Back.\" The musician looks very 1970s chic--wearing dark aviator glasses, a short, tight afro, and a wide-collared nylon shirt. Light sparkles from the corner of his glasses. \r\n\r\nThe print was made at the papermaking studio, Dieu Donné. It is composed of a series of pulp-paper circles that are grouped together like giant Ben-Day dots. To make the image, Ligon made a drawing based on the album cover that was then printed on mylar. Stencils were cut from the mylar sheets and paper pulp was pushed through the cut-out circles onto a light blue sheet of paper. The raised circles of black and white paper pulp give the image a three-dimensional presence.",
        "labeltext": "",
