        "contact": "am_asianmediterranean@harvard.edu",
        "description": "On a terrace and under a moonlit sky with two flying cranes is a Virahotkanthita Nayika (“One Distressed by Separation”), a heroine who waits and yearns for her lover to return from a long journey. She dramatically reclines across a cluster of large pillows. Her head rests back to face her female attendant who is slightly bent over her. The heroine is bare-chested and wears a green skirt as well as elaborate jewelry. She holds in her right hand the mouthpiece of a hookah. Rajput Style.",
