                "format": "image/jpeg",
                "description": "Golden sunlight fills the sky, and reflects off the water of a harbor. In the middle distance at left, a blocky, stone building with a tower rising from its center, stands on a platform in the water. A few figures that can be seen walking on the platform are reflected on the calm surface of the water, alongside the tower. Closer to us, at center left, three figures sit in a long shallow rowboat. In the background, low on the horizon, sunlight glints off sailboats here and there in the distance, and off buildings on a low hill rising at center right.",
