                "idsid": 481842013,
                "format": "image/jpeg",
                "description": "\r\nThis oval-shaped painted portrait depicts a pale-skinned woman, who stares directly at the viewer. She is seated on a chair at a table with a mirror and an array of flowers, a blue ribbon, and cosmetic tools laid in front of her. Her right hand holds a small gold container of pink blusher powder near her chest. Her left hand is raised toward her face, holding a small gold-handled brush with pink pigment on the tip. Her cheeks glow with the pink powder and her lips are glossy with a matching pink. Her grey hair is carefully arranged with small curls around her ears and small blue flowers are woven into the hair above her forehead. She wears a lace-trimmed white peignoir over her shoulders, tied with a pink ribbon, and a matching dress with pink ribbons and voluminous lace sleeves. A bracelet on her right arm shows a cameo of Louis XV.",
