                "format": "image/jpeg",
                "description": "The vessel has a tall neck, shallow rim, two horizontal handles and one long handle which connects to the rim.  In red, black, and white there is a scene in two tiers.  The lower tier is bordered in ivy and depicts a man with a lion-shaped headdress holding a complicated object while three figures look on.  One figure wears a helmet and holds a long stick, while the other two characters wear robes.  The upper tier has 6 men in helmets and armor who run while carrying shields and spears.  The rest of the vessel is painted black.",
