                "format": "image/jpeg",
                "description": "Layered gray lines and soft shading with reddish highlights show a horse mid-stride, as it gallops around an indoor ring. A man wearing green jockey’s silks and a cap, holds a riding crop over his head, as he sits on the back end of the horse, facing backwards. He leans back slightly, both his feet kicking out as he tries to maintain balance. The horse is not saddled or bridled and its neck is thrust forward, its tongue hanging from its open mouth. Across the white background, faint concentric lines circle outward beyond the ring, seeming to indicate empty stands.",
