                "idsid": 423290977,
                "format": "image/jpeg",
                "description": "Black and white photographs float in white space with glass and other materials interspersed. At middle left is the face of actress Anna May Wong in three quarter profile. To the right, three more faces appear in a descending semicircle. A light haired woman looks at us and slightly lower and to the right the face of a smiling woman looks away. The cluster resolves with the image of the full face and neck of a woman who looks directly at the viewer and wears a tall headdress, and to her left is a giraffe. At upper right is a zebra, next to the face of a woman in a striped outfit.",
