                "imageid": 483087,
                "idsid": 436863346,
                "format": "image/jpeg",
                "description": "A vertical rectangular grid is built of subdivided squares. These squares are variously: solid gray, a checkerboard pattern, striped with bands of black red and yellow tones, or made of smaller grids of multicolored straight or curved lines. These squares appear at intervals, both individually or adjacent to similar squares to form larger blocks of varying sizes. The design is made from both collaged paper and drawn or painted ink, graphite and water color. A typed label affixed in the lower margin at left reads, “Anni Albers III.1927 Design for a rug not executed”.",
                "technique": "Make:Hasselblad;Model:Hasselblad H5D-50c MS;Orientation:1;Software:Adobe Photoshop CS6 (Macintosh);",
