        "contact": "am_moderncontemporary@harvard.edu",
        "description": "",
        "provenance": "Louise Nevelson, New York NY, Constructed, 1959, Sold to Richard H. Solomon.\r\nRichard H. Solomon, New York NY, Purchased from Louise Nevelson, Gift to Fogg Art Museum, 1978.\r\n",
        "commentary": "",
        "labeltext": "Nevelson created commanding abstract sculptures assembled from bits of furniture and architectural fragments that she salvaged from the streets of New York. In her studio, she and her assistants put the pieces together using carpentry tools. Painted black and placed in an irregular organizing system of wooden crates and boxes, these urban scraps and containers take on a dramatic pictorial unity while simultaneously referencing their former use. Nevelson’s work draws on a rich history of found-object sculpture, from Marcel Duchamp’s readymades to surrealist assemblage. Like David Smith, Nevelson used modern construction materials to develop distinct forms of abstraction. Together their work opened a way for a younger generation of artists for whom mass-produced objects held more power than the painted canvas.",
