        "provenance": "The artist, 1911, sold; to the Folkwang Museum (Hagen, later Essen, Germany, 1911-1937); removed from the collection by the National Socialist (Nazi) authorities,1937, consigned; to [Theodor Fischer Gallery, Lucerne, Switzerland, for sale June 30, 1939, lot 87;]  sold [through Steinmeyer] to Paul E. Geier (1939-1981) by descent; to Gabriele Geier, (1981-2012); Estate of Gabriele Geier (2012-2014) bequest; to the Busch-Reisinger Museum, 2014.\r\n\r\nNOTE: \r\nSee Barron, et. al. for information on Steinmeyer, p. 146. n.21.\r\n\r\nThis painting was on loan to the Busch-Reisinger Museum from 1991-2014.",
