                "idsid": 43182430,
                "format": "image/jpeg",
                "description": "The painting is a landscape with three horses standing on a yellow and green surface, two are muted orange with blue and purple manes, the neck of the horse on the right is bent down, the horse on the left has two raised hooves, head facing left. Between and behind is a pinkish-brown horse facing away with head the head raised. There is a blue and black mass in lower right corner with uneven edges. The background is an undulating series of round shapes in pink, green, and gray. Streaks of white, blue, yellow and orange line the top.",
