        "dateend": 1588,
        "classification": "Manuscripts",
        "classificationid": 185,
        "medium": "Ink, opaque watercolor, and gold on paper",
        "technique": "",
        "techniqueid": "",
        "period": "Mughal period",
        "periodid": 1522,
        "century": "16th century",
        "culture": "Indian",
        "style": "",
        "signed": "",
        "state": "",
        "edition": "",
        "standardreferencenumber": "",
        "dimensions": "folio: 13.97 x 7.62 cm (5 1/2 x 3 in.)",
        "copyright": "",
        "creditline": "Harvard Art Museums/Arthur M. Sackler Museum, Gift of John Goelet",
        "department": "Department of Islamic & Later Indian Art",
        "division": "Asian and Mediterranean Art",
        "contact": "am_asianmediterranean@harvard.edu",
        "description": "The recto side of the folio features a painting depicting two figures tending to a garden. At the center of the painting is a large square fountain from which three water channels issue. Two text blocks containing Persian text written in nasta’liq script and black ink are at the top and bottom of the painting. \r\nThe verso side of the folio features two columns of Persian text written in black ink and nasta’liq script.\r\nThe folio belongs to an illustrated copy of the Divan of Anvari commissioned by the Mughal emperor Akbar (r. 1556-1605) in 1588 and in Lahore. The poet Anvari (1126-1189) is considered one of the greatest figures in Persian literature. His panegyric in honor of the Seljuq sultan, Ahmad Sanjar (r. 1118-1157) earned him royal favor and the patronage of two of Sanjar’s successors. Anvari’s poems were collected in a Divan, which contains eulogies, satire, panegyrics, and other forms of poetry and prose. \r\n",
        "provenance": "Louis J. Cartier collection. John Goelet, New York, NY, (by 1960), gift; to Fogg Art Museum, 1960.",
        "commentary": "",
        "labeltext": "",
