                "imageid": 474302,
                "idsid": 429062383,
                "format": "image/jpeg",
                "description": "The tiger is depicted in profile, with its head facing right. Its tail curls upward tightly close to its back leg, it has small uniform bumps on its back that form a texture, and a weave-like pattern carved into its legs, the head is smooth with a wide opened eye. It has two claw-like feet. The color of the jade varies from subtle creamy greens to varieties of warm and cool browns. Most of it has a thin carved line that follows its outer edge all around. This object is part of a pair.",
